 WebView web;PdfBridge pdfBridge;boolean pendingTracking=false;ValueCallback<Uri[]> files;PermissionRequest camera;GeolocationPermissions.Callback geoCallback;String geoOrigin;boolean locationRequest=false;Uri cameraOutput;boolean nativeCameraPending=false;
 protected void onCreate(Bundle state){super.onCreate(state);web=new WebView(this);FrameLayout container=new FrameLayout(this);container.setBackgroundColor(0xfff3f6fb);container.addView(web,new FrameLayout.LayoutParams(-1,-1));setContentView(container);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);if(Build.VERSION.SDK_INT>=30)getWindow().setDecorFitsSystemWindows(false);container.setOnApplyWindowInsetsListener((v,in)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets bars=in.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout()|WindowInsets.Type.ime());v.setPadding(bars.left,bars.top,bars.right,bars.bottom);return WindowInsets.CONSUMED;}v.setPadding(in.getSystemWindowInsetLeft(),in.getSystemWindowInsetTop(),in.getSystemWindowInsetRight(),in.getSystemWindowInsetBottom());return in.consumeSystemWindowInsets();});container.requestApplyInsets();
 WebSettings s=web.getSettings();s.setUserAgentString(s.getUserAgentString()+" PengadeganAndroid/15.0");s.setGeolocationEnabled(true);s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(true);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);CookieManager.getInstance().setAcceptCookie(true);
 if(WebViewFeature.isFeatureSupported(WebViewFeature.WEB_MESSAGE_LISTENER))WebViewCompat.addWebMessageListener(web,"PengadeganNative",Collections.singleton(AppConfig.ORIGIN),(view,msg,origin,main,reply)->{if(!main||!AppConfig.trusted(Uri.parse(view.getUrl()==null?"":view.getUrl())))return;try{JSONObject j=new JSONObject(msg.getData());String type=j.optString("type");if(type.equals("init")){String id=getPreferences(0).getString("device","");if(id.isEmpty()){id=UUID.randomUUID().toString();getPreferences(0).edit().putString("device",id).apply();}reply.postMessage(new JSONObject().put("type","init").put("device_id",id).put("has_token",false).toString());}else if(type.equals("token")){TokenStore.save(this,j.getString("token"));}else if(type.equals("tracking")){if(j.optBoolean("active"))askTracking();else if(TrackingService.running){startService(new Intent(this,TrackingService.class).setAction("FLUSH"));}}}catch(Exception e){Toast.makeText(this,"Koneksi aplikasi belum siap. Muat ulang halaman.",Toast.LENGTH_SHORT).show();}});else new AlertDialog.Builder(this).setMessage("Perbarui Android System WebView agar GPS aplikasi dapat digunakan.").setPositiveButton("OK",null).show();
 if(WebViewFeature.isFeatureSupported(WebViewFeature.WEB_MESSAGE_LISTENER))WebViewCompat.addWebMessageListener(web,"PengadeganAddress",Collections.singleton(AppConfig.ORIGIN),(view,msg,origin,main,reply)->{if(!main||!AppConfig.trusted(Uri.parse(view.getUrl()==null?"":view.getUrl())))return;try{JSONObject j=new JSONObject(msg.getData());double lat=j.getDouble("lat"),lng=j.getDouble("lng");String id=j.getString("id");if(!Double.isFinite(lat)||!Double.isFinite(lng)||lat<-90||lat>90||lng<-180||lng>180)return;new Thread(()->{String address="";try{android.location.Geocoder g=new android.location.Geocoder(getApplicationContext(),new Locale("id","ID"));if(android.location.Geocoder.isPresent()){List<android.location.Address> result=g.getFromLocation(lat,lng,1);if(result!=null&&!result.isEmpty()){android.location.Address first=result.get(0);address=first.getAddressLine(0);if(address==null)address="";}}}catch(Exception ignored){}final String value=address;runOnUiThread(()->{if(isFinishing()||isDestroyed())return;try{reply.postMessage(new JSONObject().put("id",id).put("address",value).toString());}catch(Exception ignored){}});},"pengadegan-address").start();}catch(Exception ignored){}});
 pdfBridge=new PdfBridge(this,web);
 web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest req){Uri u=req.getUrl();if(AppConfig.trusted(u))return false;if(Arrays.asList("https","http","tel","mailto").contains(u.getScheme()))try{startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(Exception ignored){}return true;}public void onPageFinished(WebView v,String url){if(AppConfig.trusted(Uri.parse(url))){applyDesign();pdfBridge.inject();}}public void onPageStarted(WebView v,String url,android.graphics.Bitmap icon){if(url.contains("/logout")||url.contains("/keluar")){stopService(new Intent(MainActivity.this,TrackingService.class));TokenStore.clear(MainActivity.this);}}public void onReceivedError(WebView v,WebResourceRequest req,WebResourceError err){if(req.isForMainFrame())Toast.makeText(MainActivity.this,"Koneksi gagal. Periksa internet, lalu buka ulang aplikasi.",Toast.LENGTH_LONG).show();}});
 web.setWebChromeClient(new WebChromeClient(){public void onGeolocationPermissionsShowPrompt(String origin,GeolocationPermissions.Callback cb){if(!trustedOrigin(origin)){cb.invoke(origin,false,false);return;}if(locationGranted()){cb.invoke(origin,true,false);return;}if(geoCallback!=null)geoCallback.invoke(geoOrigin,false,false);geoCallback=cb;geoOrigin=origin;requestLocation();}public void onGeolocationPermissionsHidePrompt(){geoCallback=null;geoOrigin=null;}public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> cb,FileChooserParams p){if(files!=null)files.onReceiveValue(null);files=cb;boolean image=false;for(String accept:p.getAcceptTypes())if(accept!=null&&accept.toLowerCase(java.util.Locale.ROOT).startsWith("image/"))image=true;if(image){if(p.isCaptureEnabled()){nativeCameraPending=true;if(checkSelfPermission(android.Manifest.permission.CAMERA)==PackageManager.PERMISSION_GRANTED)launchDeviceCamera();else requestPermissions(new String[]{android.Manifest.permission.CAMERA},15);}else openDeviceGallery();return true;}try{startActivityForResult(p.createIntent(),12);}catch(Exception e){files.onReceiveValue(null);files=null;}return true;}public void onPermissionRequest(PermissionRequest req){runOnUiThread(()->{if(!trustedOrigin(req.getOrigin().toString())) {req.deny();return;}camera=req;if(checkSelfPermission(android.Manifest.permission.CAMERA)==PackageManager.PERMISSION_GRANTED)grantCamera();else requestPermissions(new String[]{android.Manifest.permission.CAMERA},13);});}});
 web.setDownloadListener((url,ua,disposition,mime,length)->{if(!AppConfig.trusted(Uri.parse(url)))return;try{DownloadManager.Request req=new DownloadManager.Request(Uri.parse(url));String cookie=CookieManager.getInstance().getCookie(url);if(cookie!=null)req.addRequestHeader("Cookie",cookie);req.addRequestHeader("User-Agent",ua);req.setNotificationVisibility(DownloadManager.Request.VISIBILITY_VISIBLE_NOTIFY_COMPLETED);req.setDestinationInExternalPublicDir(Environment.DIRECTORY_DOWNLOADS,URLUtil.guessFileName(url,disposition,mime));((DownloadManager)getSystemService(DOWNLOAD_SERVICE)).enqueue(req);Toast.makeText(this,"Unduhan dimulai.",Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,"Unduhan gagal.",Toast.LENGTH_LONG).show();}});
 if(getPreferences(0).getInt("installed_v",0)<16){web.clearCache(true);getPreferences(0).edit().putInt("installed_v",16).apply();}
 web.loadUrl(AppConfig.BASE+"/");}
 boolean locationGranted(){return checkSelfPermission(android.Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED||checkSelfPermission(android.Manifest.permission.ACCESS_COARSE_LOCATION)==PackageManager.PERMISSION_GRANTED;}
 boolean trustedOrigin(String origin){try{Uri u=Uri.parse(origin);return "https".equals(u.getScheme())&&"pengadegan.datawebs.my.id".equals(u.getHost())&&(u.getPort()==-1||u.getPort()==443);}catch(Exception e){return false;}}
 void requestLocation(){if(locationRequest)return;locationRequest=true;requestPermissions(new String[]{android.Manifest.permission.ACCESS_FINE_LOCATION,android.Manifest.permission.ACCESS_COARSE_LOCATION},11);}
 void openDeviceGallery(){
  // No camera intent for an input without capture=environment.
  // PPPK's explicit Galeri button must open the gallery, not the camera.
  nativeCameraPending=false;
  try { Intent intent=new Intent(Intent.ACTION_GET_CONTENT);intent.setType("image/*");intent.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(Intent.createChooser(intent,"Pilih foto dari Galeri"),12); }
  catch(Exception e){if(files!=null){files.onReceiveValue(null);files=null;}Toast.makeText(this,"Galeri tidak tersedia pada perangkat.",Toast.LENGTH_LONG).show();}
 }
 void launchDeviceCamera(){
 nativeCameraPending=false;
 try{java.io.File dir=new java.io.File(getCacheDir(),"camera");if(!dir.exists()&&!dir.mkdirs())throw new java.io.IOException("Kamera tidak dapat menyiapkan penyimpanan sementara.");java.io.File file=java.io.File.createTempFile("pengadegan-",".jpg",dir);cameraOutput=androidx.core.content.FileProvider.getUriForFile(this,getPackageName()+".fileprovider",file);Intent capture=new Intent(android.provider.MediaStore.ACTION_IMAGE_CAPTURE);capture.putExtra(android.provider.MediaStore.EXTRA_OUTPUT,cameraOutput);capture.setClipData(ClipData.newRawUri("Foto kamera",cameraOutput));capture.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);startActivityForResult(capture,16);}catch(Exception e){finishDeviceCamera(false);Toast.makeText(this,"Kamera bawaan belum dapat dibuka. Periksa izin Kamera dan aplikasi kamera HP.",Toast.LENGTH_LONG).show();}}
 void finishDeviceCamera(boolean accepted){Uri result=cameraOutput;cameraOutput=null;nativeCameraPending=false;if(files!=null){ValueCallback<Uri[]> callback=files;files=null;callback.onReceiveValue(accepted&&result!=null?new Uri[]{result}:null);}}
 void grantCamera(){if(camera==null)return;ArrayList<String> granted=new ArrayList<>();for(String resource:camera.getResources())if(resource.equals(PermissionRequest.RESOURCE_VIDEO_CAPTURE))granted.add(resource);if(granted.isEmpty())camera.deny();else camera.grant(granted.toArray(new String[0]));camera=null;}
 void askTracking(){if(TokenStore.read(this).isEmpty())return;pendingTracking=true;if(checkSelfPermission(android.Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){new AlertDialog.Builder(this).setMessage("Lokasi digunakan selama Anda bertugas, termasuk saat layar terkunci. Notifikasi pelacakan akan terlihat. Izinkan lokasi akurat untuk melanjutkan.").setPositiveButton("Izinkan",(d,w)->requestLocation()).setNegativeButton("Batal",(d,w)->pendingTracking=false).show();return;}if(Build.VERSION.SDK_INT>=33 && checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},14);return;}startTracking();}
 void startTracking(){if(isFinishing()||TokenStore.read(this).isEmpty())return;if(checkSelfPermission(android.Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){pendingTracking=false;Toast.makeText(this,"Aktifkan Lokasi akurat untuk memulai pelacakan.",Toast.LENGTH_LONG).show();return;}pendingTracking=false;try{startForegroundService(new Intent(this,TrackingService.class));}catch(Exception e){Toast.makeText(this,"GPS belum aktif. Buka kembali halaman Jam Kerja.",Toast.LENGTH_LONG).show();}}
 public void onRequestPermissionsResult(int code,String[] p,int[] g){super.onRequestPermissionsResult(code,p,g);if(code==15){if(nativeCameraPending&&checkSelfPermission(android.Manifest.permission.CAMERA)==PackageManager.PERMISSION_GRANTED)launchDeviceCamera();else{finishDeviceCamera(false);Toast.makeText(this,"Izinkan Kamera pada pengaturan aplikasi untuk mengambil foto.",Toast.LENGTH_LONG).show();}}else if(code==13){if(g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)grantCamera();else if(camera!=null){camera.deny();camera=null;}}else if(code==14){startTracking();}else if(code==11){locationRequest=false;boolean granted=locationGranted();if(geoCallback!=null){GeolocationPermissions.Callback cb=geoCallback;String origin=geoOrigin;geoCallback=null;geoOrigin=null;cb.invoke(origin,granted,false);}if(granted){if(pendingTracking){if(checkSelfPermission(android.Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED)askTracking();else{pendingTracking=false;Toast.makeText(this,"Pratinjau lokasi diizinkan. Aktifkan Lokasi akurat untuk pelacakan tugas.",Toast.LENGTH_LONG).show();}}}else{pendingTracking=false;new AlertDialog.Builder(this).setTitle("Izin lokasi diperlukan").setMessage("Aktifkan izin Lokasi untuk aplikasi Pengadegan. Pilih lokasi akurat untuk pencatatan kerja.").setPositiveButton("Pengaturan",(d,w)->startActivity(new Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName())))).setNegativeButton("Tutup",null).show();}}}
 protected void onActivityResult(int code,int result,Intent data){super.onActivityResult(code,result,data);if(code==16){finishDeviceCamera(result==RESULT_OK);return;}if(code==12&&files!=null){files.onReceiveValue(WebChromeClient.FileChooserParams.parseResult(result,data));files=null;}}
 public void onBackPressed(){if(web.canGoBack())web.goBack();else super.onBackPressed();}
 void applyDesign(){try{java.io.InputStream stream=getAssets().open("app-v2.css");java.io.ByteArrayOutputStream output=new java.io.ByteArrayOutputStream();byte[] bytes=new byte[4096];int n;while((n=stream.read(bytes))!=-1)output.write(bytes,0,n);stream.close();String css=output.toString("UTF-8");web.evaluateJavascript("(function(){document.documentElement.classList.add('pengadegan-native');var s=document.getElementById('pengadegan-app-v2');if(!s){s=document.createElement('style');s.id='pengadegan-app-v2';document.head.appendChild(s);}s.textContent="+JSONObject.quote(css)+";})()",null);}catch(Exception ignored){}}
